// Some portions generated by Claude
import { useEffect, useId, useRef, useState, type ReactNode } from "react";
import { Icon } from "./icons.tsx";
import type { GuideSection } from "./explorer-help.ts";

/**
 * A "?" button that opens a small panel with the details most readers can skip, like the Workbench's own help buttons
 * (helpTip in classic/workbenchViews.ts). A press elsewhere closes it; Escape closes it and returns to the button
 * before the explorer's own Escape (details card, selection) gets a turn.
 *
 * `align` picks the button edge a floating panel lines up with: "end" for a button near the right edge of the explorer.
 * The side panels, the query drawer and the details cards clip what overflows them, so there `inline` opens the panel
 * in the flow instead: the help's box takes no space of its own (display: contents) and the panel wraps onto a line of
 * its own under the heading the button follows, pushing the rest down.
 */
export function HelpTip({ label, align = "start", wide = false, inline = false, children }: {
  label: string;
  align?: "start" | "end";
  wide?: boolean;
  inline?: boolean;
  children: ReactNode;
}) {
  const [open, setOpen] = useState(false);
  const panelId = useId();
  const root = useRef<HTMLSpanElement>(null);
  const button = useRef<HTMLButtonElement>(null);
  const atEnd = align === "end";
  useEffect(() => {
    if (!open) return;
    const pressOutside = (event: PointerEvent) => {
      if (!root.current?.contains(event.target as Node)) setOpen(false);
    };
    // In the capture phase, so the explorer's Escape (which closes cards and clears the selection) does not see it.
    const escape = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      event.preventDefault();
      event.stopPropagation();
      setOpen(false);
      button.current?.focus();
    };
    document.addEventListener("pointerdown", pressOutside, true);
    document.addEventListener("keydown", escape, true);
    return () => {
      document.removeEventListener("pointerdown", pressOutside, true);
      document.removeEventListener("keydown", escape, true);
    };
  }, [open]);
  return (
    <span ref={root} className={`help-tip${inline ? " is-inline" : ""}`}>
      <button
        ref={button}
        className="workbench-action workbench-action--ghost workbench-action--icon help-tip-button"
        type="button"
        aria-label={label}
        title={label}
        aria-expanded={open}
        aria-controls={panelId}
        onClick={() => setOpen((current) => !current)}
      >
        <Icon name="help" />
      </button>
      <div
        id={panelId}
        className={`help-tip-panel${atEnd ? " is-end" : ""}${wide ? " is-wide" : ""}${inline ? " is-inline" : ""}`}
        role="note"
        hidden={!open}
      >
        {children}
      </div>
    </span>
  );
}

/** A guide (explorer-help.ts) as a help panel: a definition list of gestures per section, then the notes. */
export function GuideContent({ sections }: { sections: readonly GuideSection[] }) {
  return (
    <>
      {sections.map((section) => (
        <section key={section.title} className="help-guide-section">
          <h3>{section.title}</h3>
          {section.items.length ? (
            <dl>
              {section.items.map((item) => (
                <div key={item.keys}>
                  <dt>{item.keys}</dt>
                  <dd>{item.text}</dd>
                </div>
              ))}
            </dl>
          ) : null}
          {(section.notes ?? []).map((note) => (
            <p key={note}>{note}</p>
          ))}
        </section>
      ))}
    </>
  );
}
